#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Hash table entry structure
typedef struct {
    char *key;
    void *value;
    int is_occupied;  // 1 = occupied, 0 = empty, -1 = deleted
} HashEntry;

// Hash table structure
typedef struct {
    HashEntry *entries;
    size_t size;      // current number of elements
    size_t capacity;  // total capacity
} HashTable;

// Hash function (djb2)
static unsigned long hash_string(const char *key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash;
}

// Helper function to find the right slot
static size_t find_slot(HashTable *ht, const char *key, int create_new) {
    unsigned long hash = hash_string(key);
    size_t index = hash % ht->capacity;

    for (size_t i = 0; i < ht->capacity; i++) {
        size_t current_index = (index + i) % ht->capacity;

        if (ht->entries[current_index].is_occupied == 0) {
            // Empty slot found
            if (create_new) {
                return current_index;
            }
            return -1; // Not found
        }

        if (ht->entries[current_index].is_occupied == 1 &&
            strcmp(ht->entries[current_index].key, key) == 0) {
            // Key found
            return current_index;
        }
        // is_occupied == -1 means deleted, continue probing
    }

    // Table is full (no empty slots for new entries)
    return create_new ? -1 : -1;
}

// Create a new hash table
HashTable *ht_create(size_t capacity) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->capacity = capacity;
    ht->size = 0;
    ht->entries = (HashEntry *)calloc(capacity, sizeof(HashEntry));
    if (!ht->entries) {
        free(ht);
        return NULL;
    }

    // Initialize all entries as empty
    for (size_t i = 0; i < capacity; i++) {
        ht->entries[i].is_occupied = 0;
    }

    return ht;
}

// Set a key-value pair
int ht_set(HashTable *ht, const char *key, void *value) {
    if (!ht || !key) return 0;

    // Check if we need to resize (simple threshold: 70% full)
    if ((double)ht->size / ht->capacity > 0.7) {
        size_t new_capacity = ht->capacity * 2;
        HashTable *new_ht = ht_create(new_capacity);
        if (!new_ht) return 0;

        // Rehash existing entries
        for (size_t i = 0; i < ht->capacity; i++) {
            if (ht->entries[i].is_occupied == 1) {
                ht_set(new_ht, ht->entries[i].key, ht->entries[i].value);
            }
        }

        // Replace old hash table
        free(ht->entries);
        ht->entries = new_ht->entries;
        ht->capacity = new_ht->capacity;
        free(new_ht);
    }

    // Find or create slot
    size_t index = find_slot(ht, key, 1);
    if (index == (size_t)-1) return 0; // Table full

    // If key exists, update value (don't increment size)
    if (ht->entries[index].is_occupied == 1) {
        free(ht->entries[index].key); // Free old key
    } else {
        ht->size++;
    }

    // Copy key
    ht->entries[index].key = strdup(key);
    if (!ht->entries[index].key) return 0;

    ht->entries[index].value = value;
    ht->entries[index].is_occupied = 1;

    return 1;
}

// Get value by key
void *ht_get(HashTable *ht, const char *key) {
    if (!ht || !key) return NULL;

    size_t index = find_slot(ht, key, 0);
    if (index == (size_t)-1) return NULL;

    return ht->entries[index].value;
}

// Delete a key-value pair
int ht_delete(HashTable *ht, const char *key) {
    if (!ht || !key) return 0;

    size_t index = find_slot(ht, key, 0);
    if (index == (size_t)-1) return 0;

    // Mark as deleted
    free(ht->entries[index].key);
    ht->entries[index].key = NULL;
    ht->entries[index].value = NULL;
    ht->entries[index].is_occupied = -1;
    ht->size--;

    return 1;
}

// Destroy the hash table
void ht_destroy(HashTable *ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->entries[i].is_occupied == 1) {
            free(ht->entries[i].key);
            // Note: We don't free values as they're void* provided by the user
        }
    }

    free(ht->entries);
    free(ht);
}

// Example usage
int main() {
    HashTable *ht = ht_create(16);

    int a = 1, b = 2, c = 3;

    ht_set(ht, "apple", &a);
    ht_set(ht, "banana", &b);
    ht_set(ht, "orange", &c);

    int *val = ht_get(ht, "banana");
    if (val) {
        printf("banana: %d\n", *val);
    }

    ht_delete(ht, "banana");

    val = ht_get(ht, "banana");
    if (!val) {
        printf("banana deleted\n");
    }

    ht_destroy(ht);
    return 0;
}
