#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;          // Pointer to the array
    size_t size;        // Number of elements in the array
    size_t capacity;    // Current capacity (allocated memory)
} Vector;

// Create a new empty vector
Vector* vector_create() {
    Vector *vec = (Vector*)malloc(sizeof(Vector));
    if (!vec) return NULL;

    vec->data = NULL;
    vec->size = 0;
    vec->capacity = 0;

    return vec;
}

// Destroy the vector and free all memory
void vector_destroy(Vector *vec) {
    if (vec) {
        free(vec->data);
        free(vec);
    }
}

// Ensure vector has at least 'new_capacity' capacity
void vector_reserve(Vector *vec, size_t new_capacity) {
    if (new_capacity <= vec->capacity) return;

    int *new_data = (int*)realloc(vec->data, new_capacity * sizeof(int));
    if (!new_data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    vec->data = new_data;
    vec->capacity = new_capacity;
}

// Helper function to resize the vector (typically doubles capacity)
static void vector_resize(Vector *vec, size_t new_capacity) {
    vector_reserve(vec, new_capacity);
}

// Add element to the end (amortized O(1))
void vector_push(Vector *vec, int value) {
    // Double capacity if full, otherwise use current capacity
    if (vec->size == vec->capacity) {
        size_t new_capacity = (vec->capacity == 0) ? 1 : vec->capacity * 2;
        vector_resize(vec, new_capacity);
    }

    vec->data[vec->size++] = value;
}

// Remove and return last element (O(1))
int vector_pop(Vector *vec) {
    if (vec->size == 0) {
        fprintf(stderr, "Error: pop from empty vector\n");
        exit(EXIT_FAILURE);
    }

    int value = vec->data[--vec->size];
    return value;
}

// Shrink capacity to fit current size (releases excess memory)
void vector_shrink_to_fit(Vector *vec) {
    if (vec->size == 0) {
        // Special case: if empty, free all memory
        free(vec->data);
        vec->data = NULL;
        vec->capacity = 0;
    } else if (vec->size < vec->capacity) {
        int *new_data = (int*)realloc(vec->data, vec->size * sizeof(int));
        if (!new_data) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        vec->data = new_data;
        vec->capacity = vec->size;
    }
}

// Get element at index (bounds checking)
int vector_get(Vector *vec, size_t index) {
    if (index >= vec->size) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }
    return vec->data[index];
}

// Set element at index (bounds checking)
void vector_set(Vector *vec, size_t index, int value) {
    if (index >= vec->size) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }
    vec->data[index] = value;
}

