Here's a numerically stable, in-place softmax function for a float array in C:

```c
#include <math.h>
#include <stddef.h>

void softmax_stable(float *arr, size_t n) {
    if (arr == NULL || n == 0) return;

    /* 1. Find the maximum value – this is the key to numerical stability.
     *    Subtracting the max prevents overflow in the exponentiation step. */
    float max = arr[0];
    for (size_t i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    /* 2. Subtract max, exponentiate, and accumulate the sum. */
    float sum = 0.0f;
    for (size_t i = 0; i < n; i++) {
        arr[i] = expf(arr[i] - max);  // expf = float-safe exp
        sum += arr[i];
    }

    /* 3. Normalize in-place.
     *    After step 2, sum >= 1.0 (at least one element is exp(0) = 1),
     *    so division is always safe. */
    for (size_t i = 0; i < n; i++) {
        arr[i] /= sum;
    }
}
```

### How it works
1. **Max subtraction**: `arr[i] - max` shifts the input so the largest value becomes `0`, guaranteeing `exp(...)` ≤ 1 and eliminating overflow risk.
2. **Exponentiation & summation**: Each element becomes `e^(x_i - max)`, and we sum them to get the normalization denominator.
3. **In-place division**: Every element is divided by the sum, producing probabilities that sum to 1.0.

The function uses `expf` for float precision, handles edge cases (`NULL`/empty array), and modifies the original array directly with O(n) time and O(1) extra space.

Here's a clean, portable C function that parallelizes an independent loop over `N` items across `T` POSIX threads, distributes work evenly, and joins all threads before returning.

```c
#include <pthread.h>
#include <stdlib.h>

/* Argument passed to each thread */
typedef struct {
    int start;
    int end;
    void (*process)(int);  /* function to apply to each item */
} loop_args_t;

/* Thread routine: processes items [start, end) */
void *thread_routine(void *arg) {
    loop_args_t *args = (loop_args_t *)arg;
    for (int i = args->start; i < args->end; ++i) {
        args->process(i);  /* independent work per item */
    }
    free(args);
    return NULL;
}

/* Parallelize a loop:  for (int i = 0; i < N; i++) process(i)  */
void parallel_loop(int N, int T, void (*process)(int)) {
    if (N <= 0 || T <= 0 || !process) return;

    pthread_t *threads = malloc(T * sizeof(pthread_t));
    if (!threads) return;

    for (int t = 0; t < T; ++t) {
        /* Evenly split [0, N) across T threads */
        int start = (N * t) / T;
        int end   = (N * (t + 1)) / T;

        loop_args_t *args = malloc(sizeof(loop_args_t));
        if (!args) { /* cleanup existing threads if allocation fails */
            for (int k = 0; k < t; ++k) pthread_cancel(threads[k]);
            free(threads);
            return;
        }
        args->start = start;
        args->end   = end;
        args->process = process;

        pthread_create(&threads[t], NULL, thread_routine, args);
    }

    /* Join all threads before returning */
    for (int t = 0; t < T; ++t) {
        pthread_join(threads[t], NULL);
    }

    free(threads);
}

/* Example usage --------------------------------------------------- */
#include <stdio.h>

void process_item(int i) {
    /* Replace with actual independent work */
    // printf("Processing item %d\n", i);
}

int main(void) {
    int N = 1000;
    int T = 4;
    parallel_loop(N, T, process_item);
    return 0;
}
```

**Key design points:**
- **Even distribution**: `start = (N * t) / T`, `end = (N * (t + 1)) / T` ensures roughly equal workloads with no manual remainder handling.
- **Thread args**: A small `struct` carries the range and the user's processing function.
- **Safety**: `malloc`/`free` for thread args; graceful cleanup on allocation failure.
- **Guaranteed join**: All `T` threads are joined in a loop before `parallel_loop` returns.
- **No synchronization overhead**: Since items are independent, each thread only reads its assigned range and calls the user-provided `process(i)`.

Here's a C function that tokenizes a string by whitespace into an array of strings, with a cleanup function, without modifying the input:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/**
 * Tokenizes a string by whitespace into an array of strings.
 * The input string is not modified.
 * 
 * @param str The input string to tokenize
 * @return A NULL-terminated array of strings (tokens)
 *         Returns NULL if input is NULL or allocation fails
 */
char** tokenize(const char* str) {
    if (str == NULL) {
        return NULL;
    }

    // First pass: count tokens
    size_t count = 0;
    const char* p = str;

    while (*p) {
        // Skip whitespace
        while (*p && isspace((unsigned char)*p)) {
            p++;
        }

        // If we found a non-whitespace character, we have a token
        if (*p) {
            count++;

            // Skip to the end of the token
            while (*p && !isspace((unsigned char)*p)) {
                p++;
            }
        }
    }

    // Allocate memory for the array of pointers (+1 for NULL terminator)
    char** tokens = (char**)malloc((count + 1) * sizeof(char*));
    if (tokens == NULL) {
        return NULL;
    }

    // Initialize the array
    for (size_t i = 0; i <= count; i++) {
        tokens[i] = NULL;
    }

    // Second pass: extract tokens
    p = str;
    size_t tokenIndex = 0;

    while (*p && tokenIndex < count) {
        // Skip whitespace
        while (*p && isspace((unsigned char)*p)) {
            p++;
        }

        if (*p) {
            // Find the end of the token
            const char* tokenStart = p;
            while (*p && !isspace((unsigned char)*p)) {
                p++;
            }

            size_t tokenLength = p - tokenStart;

            // Allocate and copy the token
            char* token = (char*)malloc(tokenLength + 1); // +1 for null terminator
            if (token == NULL) {
                // Cleanup on allocation failure
                free_tokens(tokens);
                return NULL;
            }

            memcpy(token, tokenStart, tokenLength);
            token[tokenLength] = '\0';

            tokens[tokenIndex++] = token;
        }
    }

    tokens[tokenIndex] = NULL; // Ensure NULL termination
    return tokens;
}

/**
 * Frees all memory allocated by the tokenize function.
 * Safe to call with NULL.
 * 
 * @param tokens The array of tokens to free
 */
void free_tokens(char** tokens) {
    if (tokens == NULL) {
        return;
    }

    for (int i = 0; tokens[i] != NULL; i++) {
        free(tokens[i]);
    }
    free(tokens);
}

/* Example usage */
int main() {
    const char* testStrings[] = {
        "Hello World",
        "  Multiple   spaces   between   words  ",
        "Tabs\tand\tnewlines\n",
        "NoWhitespace",
        "   Leading and trailing whitespace   ",
        "",
        NULL
    };

    for (int i = 0; testStrings[i] != NULL; i++) {
        printf("Input: \"%s\"\n", testStrings[i]);
        char** tokens = tokenize(testStrings[i]);

        if (tokens != NULL) {
            printf("Tokens:\n");
            for (int j = 0; tokens[j] != NULL; j++) {
                printf("  [%d]: \"%s\"\n", j, tokens[j]);
            }
            free_tokens(tokens);
        } else {
            printf("Tokenization failed\n");
        }
        printf("\n");
    }

    return 0;
}
```

**Key features:**

1. **No input modification**: The function works with a `const char*` input and makes copies of each token.

2. **Proper cleanup**: The `free_tokens()` function properly frees all memory allocated by `tokenize()`:
   - Frees each individual token string
   - Frees the array of pointers

3. **NULL safety**: Both functions handle NULL input gracefully.

4. **Whitespace handling**: Uses `isspace()` from `<ctype.h>` to handle all whitespace characters (spaces, tabs, newlines, etc.).

5. **Two-pass approach**: 
   - First pass counts tokens to allocate the exact amount of memory needed
   - Second pass extracts and stores the tokens

6. **Memory management**: 
   - Allocates only the memory needed for each token
   - Properly handles allocation failures with cleanup
   - Ensures NULL termination of the token array

7. **Portability**: Uses standard C library functions and works on any platform.

The example in `main()` demonstrates usage with various test cases, including multiple spaces, tabs, newlines, no whitespace, leading/trailing whitespace, and empty strings.

Here is a C library that abstracts away the details of `mmap` versus `fread`. It provides a unified interface (`file_map`, `file_unmap`, `file_get_data`, `file_get_size`) so the caller doesn't need to know which backend is used.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#ifdef _WIN32
    // Windows doesn't have mmap; we'll only implement fread fallback for brevity
    #define USE_MMAP 0
#else
    #include <sys/mman.h>
    #define USE_MMAP 1
#endif

// Internal structure to track file data and its source
typedef struct {
    void *data;
    size_t size;
    int is_mmap; // 1 if mmap'd, 0 if fread'd
#if USE_MMAP
    int fd;      // keep fd open for munmap
#endif
} FileData;

// Attempt to load a file using mmap, with fallback to fread
FileData *file_map(const char *path) {
    FileData *file = (FileData *)malloc(sizeof(FileData));
    if (!file) return NULL;

    file->data = NULL;
    file->size = 0;
    file->is_mmap = 0;
#if USE_MMAP
    file->fd = -1;
#endif

#if USE_MMAP
    // Try mmap first
    file->fd = open(path, O_RDONLY);
    if (file->fd != -1) {
        struct stat st;
        if (fstat(file->fd, &st) == 0 && st.st_size > 0) {
            file->size = (size_t)st.st_size;
            file->data = mmap(NULL, file->size, PROT_READ, MAP_PRIVATE, file->fd, 0);
            if (file->data != MAP_FAILED) {
                file->is_mmap = 1;
                return file;
            }
        }
        // If mmap failed, close fd and fall through to fread
        close(file->fd);
        file->fd = -1;
    }
#endif

    // Fallback to fread
    FILE *fp = fopen(path, "rb");
    if (!fp) {
        free(file);
        return NULL;
    }

    fseek(fp, 0, SEEK_END);
    file->size = (size_t)ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (file->size == 0) {
        fclose(fp);
        free(file);
        return NULL;
    }

    file->data = malloc(file->size);
    if (!file->data) {
        fclose(fp);
        free(file);
        return NULL;
    }

    if (fread(file->data, 1, file->size, fp) != file->size) {
        free(file->data);
        fclose(fp);
        free(file);
        return NULL;
    }

    fclose(fp);
    file->is_mmap = 0;
    return file;
}

// Unmap or free the file data
void file_unmap(FileData *file) {
    if (!file) return;

#if USE_MMAP
    if (file->is_mmap) {
        munmap(file->data, file->size);
        if (file->fd != -1) close(file->fd);
    } else {
#else
    {
#endif
        free(file->data);
    }

    free(file);
}

// Get a pointer to the file data
void *file_get_data(const FileData *file) {
    return file ? file->data : NULL;
}

// Get the size of the file data
size_t file_get_size(const FileData *file) {
    return file ? file->size : 0;
}

/*
 * Example usage:
 *
 * #include <stdio.h>
 *
 * int main(void) {
 *     FileData *f = file_map("example.txt");
 *     if (f) {
 *         printf("Loaded %zu bytes\n", file_get_size(f));
 *         // Process data...
 *         file_unmap(f);
 *     }
 *     return 0;
 * }
 */
```

### How it works:

1. **Structure**: `FileData` stores the pointer, size, and whether it was memory-mapped or loaded via `fread`. On POSIX, it also keeps the file descriptor open (required until `munmap`).
2. **`file_map(path)`**:
   - Tries `mmap` with `PROT_READ` and `MAP_PRIVATE` (read-only, copy-on-write).
   - If that fails (e.g., file on a filesystem that doesn't support `mmap`), it falls back to `fread` into a `malloc`'d buffer.
   - Returns `NULL` on error.
3. **`file_unmap(file)`**: Calls `munmap` + `close` if it was mmap'd, or `free` if it was fread'd.
4. **`file_get_data` / `file_get_size`**: Clean accessors.

The caller interacts entirely through these functions and never needs to know the underlying mechanism.

Here's a self-contained C function that greedily matches the longest vocabulary token at the start of a buffer, returning the token index and number of characters consumed.

```c
#include <string.h>
#include <stddef.h>

/*
 * Greedily matches the longest token from `vocabulary` at the start of `buffer`.
 *
 * Parameters:
 *   buffer        - const char* text buffer to scan
 *   buffer_len    - number of valid bytes in buffer (0-termination not required)
 *   vocabulary    - const char** array of token strings
 *   vocab_size    - number of entries in vocabulary
 *   out_length    - output: length in bytes of the matched token (set even on no-match to 0)
 *   out_id        - output: index in `vocabulary` of the matched token, or -1 if no match
 *
 * Returns:
 *   1 if a token was matched
 *   0 if no vocabulary token matches the start of the buffer
 *
 * Tie-breaking:
 *   If multiple tokens have the same maximal length, the first one encountered in the array wins.
 */
int greedy_token_match(const char* buffer, size_t buffer_len,
                       const char** vocabulary, size_t vocab_size,
                       size_t* out_length, int* out_id)
{
    if (!buffer || !vocabulary || !out_length || !out_id)
        return 0;
    if (buffer_len == 0 || vocab_size == 0)
        return 0;

    size_t best_len = 0;
    int best_id = -1;

    for (size_t i = 0; i < vocab_size; ++i) {
        const char* token = vocabulary[i];
        if (!token) continue;

        size_t token_len = strlen(token);
        if (token_len == 0) continue;            // skip empty tokens
        if (token_len > buffer_len) continue;    // too long for remaining buffer

        if (strncmp(buffer, token, token_len) == 0) {
            if (token_len > best_len) {          // strictly longer wins
                best_len = token_len;
                best_id  = (int)i;
            }
            // if token_len == best_len we keep the first one found
        }
    }

    if (best_id >= 0) {
        *out_length = best_len;
        *out_id     = best_id;
        return 1;
    }

    *out_length = 0;
    *out_id     = -1;
    return 0;
}
```

### Quick usage example
```c
int main(void) {
    const char* buf = "function_call";
    const char* vocab[] = {"func", "function", "fun", "ction_call"};
    size_t vn = sizeof(vocab) / sizeof(vocab[0]);
    size_t matched_len;
    int matched_id;

    if (greedy_token_match(buf, strlen(buf), vocab, vn, &matched_len, &matched_id)) {
        printf("Matched token #%d, consumed %zu bytes: \"%.*s\"\n",
               matched_id, matched_len, (int)matched_len, buf);
    } else {
        printf("No token matched.\n");
    }
    return 0;
}
```
Output:
```
Matched token #1, consumed 8 bytes: "function"
```
- Time complexity: O(N * M) where N = vocab size, M = average token length (due to `strlen` + `strncmp`). For large vocabularies, consider precomputing token lengths or using a trie.
- No heap allocation, fully reentrant, and works with binary-safe buffers as long as tokens are null‑terminated C strings.

Here's a C function set that handles UTF-8 and UTF-32 conversion with proper error handling:

```c
#include <stdint.h>
#include <stddef.h>

// Error code for invalid conversions
#define INVALID_CODEPOINT 0xFFFFFFFFU

/**
 * @brief Decode a UTF-8 sequence to a UTF-32 codepoint
 * 
 * @param utf8      Pointer to UTF-8 bytes
 * @param length    Length of UTF-8 sequence (can be 0 if unknown)
 * @param bytes_used Output: number of bytes consumed (can be NULL)
 * @return UTF-32 codepoint, or INVALID_CODEPOINT on error
 */
uint32_t utf8_to_utf32(const uint8_t* utf8, size_t length, size_t* bytes_used) 
{
    if (!utf8) {
        if (bytes_used) *bytes_used = 0;
        return INVALID_CODEPOINT;
    }

    size_t consumed = 0;
    uint32_t codepoint = 0;

    // Check first byte to determine sequence length
    uint8_t first = utf8[0];

    if ((first & 0x80) == 0) { // 0xxxxxxx (ASCII)
        codepoint = first;
        consumed = 1;
    }
    else if ((first & 0xE0) == 0xC0) { // 110xxxxx (2-byte)
        if (length < 2) goto error;
        if ((utf8[1] & 0xC0) != 0x80) goto error;

        codepoint = (first & 0x1F) << 6;
        codepoint |= (utf8[1] & 0x3F);
        consumed = 2;

        // Overlong sequence check
        if (codepoint < 0x80) goto error;
    }
    else if ((first & 0xF0) == 0xE0) { // 1110xxxx (3-byte)
        if (length < 3) goto error;
        if ((utf8[1] & 0xC0) != 0x80) goto error;
        if ((utf8[2] & 0xC0) != 0x80) goto error;

        codepoint = (first & 0x0F) << 12;
        codepoint |= (utf8[1] & 0x3F) << 6;
        codepoint |= (utf8[2] & 0x3F);
        consumed = 3;

        // Overlong sequence and range checks
        if (codepoint < 0x800) goto error;
        if (codepoint >= 0xD800 && codepoint <= 0xDFFF) goto error; // Surrogate
    }
    else if ((first & 0xF8) == 0xF0) { // 11110xxx (4-byte)
        if (length < 4) goto error;
        if ((utf8[1] & 0xC0) != 0x80) goto error;
        if ((utf8[2] & 0xC0) != 0x80) goto error;
        if ((utf8[3] & 0xC0) != 0x80) goto error;

        codepoint = (first & 0x07) << 18;
        codepoint |= (utf8[1] & 0x3F) << 12;
        codepoint |= (utf8[2] & 0x3F) << 6;
        codepoint |= (utf8[3] & 0x3F);
        consumed = 4;

        // Overlong sequence and range checks
        if (codepoint < 0x10000) goto error;
        if (codepoint > 0x10FFFF) goto error; // Beyond Unicode
    }
    else {
        goto error;
    }

    if (bytes_used) *bytes_used = consumed;
    return codepoint;

error:
    if (bytes_used) *bytes_used = 1; // Skip invalid byte
    return INVALID_CODEPOINT;
}

/**
 * @brief Encode a UTF-32 codepoint to UTF-8
 * 
 * @param codepoint  UTF-32 codepoint to encode
 * @param utf8       Output buffer (must have at least 4 bytes)
 * @param max_bytes  Size of output buffer
 * @return Number of bytes written, or 0 on error
 */
size_t utf32_to_utf8(uint32_t codepoint, uint8_t* utf8, size_t max_bytes) 
{
    if (!utf8 || max_bytes < 4) return 0;

    // Validate codepoint
    if (codepoint > 0x10FFFF) return 0;
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) return 0; // Surrogates

    size_t bytes_needed = 0;

    if (codepoint <= 0x7F) { // ASCII (0-127)
        utf8[0] = (uint8_t)codepoint;
        bytes_needed = 1;
    }
    else if (codepoint <= 0x7FF) { // 2-byte (128-2047)
        if (max_bytes < 2) return 0;
        utf8[0] = 0xC0 | (uint8_t)(codepoint >> 6);
        utf8[1] = 0x80 | (uint8_t)(codepoint & 0x3F);
        bytes_needed = 2;
    }
    else if (codepoint <= 0xFFFF) { // 3-byte (2048-65535)
        if (max_bytes < 3) return 0;
        utf8[0] = 0xE0 | (uint8_t)(codepoint >> 12);
        utf8[1] = 0x80 | (uint8_t)((codepoint >> 6) & 0x3F);
        utf8[2] = 0x80 | (uint8_t)(codepoint & 0x3F);
        bytes_needed = 3;
    }
    else { // 4-byte (65536-1114111)
        if (max_bytes < 4) return 0;
        utf8[0] = 0xF0 | (uint8_t)(codepoint >> 18);
        utf8[1] = 0x80 | (uint8_t)((codepoint >> 12) & 0x3F);
        utf8[2] = 0x80 | (uint8_t)((codepoint >> 6) & 0x3F);
        utf8[3] = 0x80 | (uint8_t)(codepoint & 0x3F);
        bytes_needed = 4;
    }

    return bytes_needed;
}

// Example usage:
/*
#include <stdio.h>

int main() {
    // Test UTF-8 to UTF-32 decoding
    const uint8_t* test_utf8 = "Hello"; // ASCII
    size_t pos = 0;
    uint32_t cp;
    size_t consumed;

    printf("UTF-8 to UTF-32:\n");
    while (test_utf8[pos]) {
        cp = utf8_to_utf32(&test_utf8[pos], 4, &consumed);
        if (cp == INVALID_CODEPOINT) {
            printf("Invalid sequence at position %zu\n", pos);
            break;
        }
        printf("Codepoint: U+%04X (consumed %zu bytes)\n", cp, consumed);
        pos += consumed;
    }

    // Test UTF-32 to UTF-8 encoding
    uint32_t test_codepoints[] = {0x41, 0x00E9, 0x4E16, 0x1F600}; // A, é, 世, 😀
    uint8_t utf8_buffer[4];

    printf("\nUTF-32 to UTF-8:\n");
    for (int i = 0; i < 4; i++) {
        size_t bytes = utf32_to_utf8(test_codepoints[i], utf8_buffer, sizeof(utf8_buffer));
        if (bytes > 0) {
            printf("U+%04X -> ", test_codepoints[i]);
            for (size_t j = 0; j < bytes; j++) {
                printf("%02X ", utf8_buffer[j]);
            }
            printf("(%zu bytes)\n", bytes);
        }
    }

    return 0;
}
*/
```

## Key Features:

1. **UTF-8 Decoding (`utf8_to_utf32`)**:
   - Validates all continuation bytes (10xxxxxx pattern)
   - Checks for overlong sequences
   - Rejects UTF-16 surrogates (U+D800 to U+DFFF)
   - Handles incomplete sequences safely with `length` parameter
   - Returns `INVALID_CODEPOINT` for errors

2. **UTF-8 Encoding (`utf32_to_utf8`)**:
   - Validates codepoints (rejects surrogates and values > U+10FFFF)
   - Writes correct UTF-8 sequences based on codepoint value
   - Returns number of bytes written or 0 on error
   - Requires buffer of at least 4 bytes

3. **Safety Features**:
   - Null pointer checks
   - Buffer overflow prevention
   - Proper error handling without undefined behavior
   - Clear return codes for error conditions

The functions handle all valid Unicode codepoints (U+0000 to U+10FFFF) and properly reject invalid sequences according to the Unicode standard. The example usage in comments demonstrates how to use both functions.

Here's a portable, bounds-checked C function that reads a little-endian `uint64` followed by a protobuf-style varint from a byte buffer, advancing a cursor.

```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

/*
 * Reads a little-endian uint64 and a varint from buf starting at *cursor.
 * On success: sets *val64 and *val_varint, advances *cursor past both values,
 * and returns 0.
 * On failure: returns -1 and leaves the cursor/cvalues unspecified.
 *
 * Varint format (protobuf/google style):
 *   Each byte uses the lower 7 bits for data, MSB = 1 means "more bytes follow".
 *   Read until a byte with MSB == 0. Maximum 10 bytes for a valid 64-bit varint.
 */

int read_uint64_and_varint(const uint8_t *buf, size_t buf_size,
                           size_t *cursor,
                           uint64_t *val64, uint64_t *val_varint)
{
    if (!buf || !cursor || !val64 || !val_varint)
        return -1;
    if (*cursor > buf_size)
        return -1;

    /* ---- Read little-endian uint64 (exactly 8 bytes) ---- */
    if (*cursor + 8 > buf_size)
        return -1;

    *val64 = 0;
    for (size_t i = 0; i < 8; i++)
        *val64 |= (uint64_t)buf[*cursor + i] << (8 * i);

    *cursor += 8;

    /* ---- Read varint ---- */
    *val_varint = 0;
    for (int i = 0; i < 10; i++) {          /* 10 bytes max for 64-bit varint */
        if (*cursor + i >= buf_size)
            return -1;                        /* buffer ran out */

        uint8_t b = buf[*cursor + i];
        *val_varint |= (uint64_t)(b & 0x7F) << (7 * i);

        if (!(b & 0x80)) {                    /* last byte reached */
            *cursor += i + 1;
            return 0;
        }
    }

    /* loop finished without seeing MSB == 0 → varint > 64 bits */
    return -1;
}

/* ---------------------------------------------------------------- */
#ifdef TEST_MAIN
#include <stdio.h>

int main(void)
{
    /* Example buffer:
     *   bytes 0–7 : little-endian uint64 = 0x0102030405060708
     *   bytes 8–10: varint = 0xFF, 0xFF, 0x01  → value = (0x7F<<14)|(0x7F<<7)|0x01 = 0x1FFFFFF
     */
    uint8_t buf[] = {
        0x08, 0x07, 0x06, 0x05, 0x04, 0x03, 0x02, 0x01,   /* LE uint64 = 0x0102030405060708 */
        0xFF, 0xFF, 0x01                                       /* varint = 0x1FFFFFF */
    };
    size_t cursor = 0;
    uint64_t v64, vvar;

    int ok = read_uint64_and_varint(buf, sizeof(buf), &cursor, &v64, &vvar);
    if (ok != 0) {
        printf("read failed\n");
        return 1;
    }

    printf("cursor advanced to: %zu\n", cursor);
    printf("uint64 = %llx (expected 0102030405060708)\n", (unsigned long long)v64);
    printf("varint = %llx (expected 1ffffff)\n", (unsigned long long)vvar);

    /* Second call: cursor should now be at byte 11 (end of buffer) */
    ok = read_uint64_and_varint(buf, sizeof(buf), &cursor, &v64, &vvar);
    printf("second read returned: %d (expected -1)\n", ok);

    return 0;
}
#endif
```

**Key details:**
- **Little-endian `uint64`**: reads exactly 8 bytes, combining them with `<< (8 * i)`.
- **Varint**: standard continuation-byte scheme; loops up to 10 times (max needed for a 64-bit unsigned varint). Breaks on a byte with MSB == 0.
- **Bounds checking**: ensures the cursor never exceeds `buf_size` for either the 8-byte integer or the variable-length varint.
- **Cursor advancement**: updated in-place after each successful read (`*cursor += 8` then `*cursor += bytes_read`).
- **Return value**: `0` on success, `-1` on any underflow, null input, or varint exceeding 64 bits.

Here's a clear breakdown, working C implementation, and the key distinction between the two operations.

### 🔑 Key Difference
- **Swap `int*` contents**: You swap the **integer values** that the two pointers point to. The pointers themselves stay at the same addresses; only the data at those addresses changes.
- **Swap `int**` pointers**: You swap the **pointer variables** themselves. After the swap, each pointer now points to whatever the other was pointing to. The integers they originally pointed to are untouched unless you also dereference and swap them.

---

### 🧩 C Implementation

```c
#include <stdio.h>

// 1️⃣ Swap the contents (values) that two int* point to
void swap_int_contents(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

// 2️⃣ Swap the int** pointers themselves
void swap_int_pointers(int **a, int **b) {
    int *tmp = *a;
    *a = *b;
    *b = tmp;
}

int main(void) {
    int x = 10, y = 20;
    int *p = &x, *q = &y;
    int **pp = &p, **qq = &q;

    printf("--- Before swaps ---\n");
    printf("x = %d, y = %d\n", x, y);
    printf("*p = %d, *q = %d\n", *p, *q);
    printf("p points to %p, q points to %p\n", (void*)p, (void*)q);
    printf("pp points to %p, qq points to %p\n", (void*)pp, (void*)qq);

    // Swap the values x and y through their pointers
    swap_int_contents(p, q);

    printf("\n--- After swap_int_contents(p, q) ---\n");
    printf("x = %d, y = %d\n", x, y);       // values swapped
    printf("*p = %d, *q = %d\n", *p, *q);  // same as above

    // Re-initialize for the second demo
    int u = 100, v = 200;
    int *r = &u, *s = &v;
    int **rr = &r, **ss = &s;

    printf("\n--- Before swap_int_pointers(rr, ss) ---\n");
    printf("u = %d, v = %d\n", u, v);
    printf("*r = %d, *s = %d\n", *r, *s);
    printf("rr points to %p, ss points to %p\n", (void*)rr, (void*)ss);

    // Swap the pointer variables rr and ss
    swap_int_pointers(rr, ss);

    printf("\n--- After swap_int_pointers(rr, ss) ---\n");
    printf("u = %d, v = %d\n", u, v);       // still 100, 200 (unchanged)
    printf("*r = %d, *s = %d\n", *r, *s);  // now points to v then u
    printf("rr points to %p, ss points to %p\n", (void*)rr, (void*)ss);
    printf("r points to %p, s points to %p\n", (void*)r, (void*)s);

    return 0;
}
```

**Output:**
```
--- Before swaps ---
x = 10, y = 20
*p = 10, *q = 20
p points to 0x7ffd... (address of x), q points to 0x7ffd... (address of y)
pp points to 0x7ffd..., qq points to 0x7ffd...

--- After swap_int_contents(p, q) ---
x = 20, y = 10
*p = 20, *q = 10

--- Before swap_int_pointers(rr, ss) ---
u = 100, v = 200
*r = 100, *s = 200
rr points to 0x7ffd..., ss points to 0x7ffd...

--- After swap_int_pointers(rr, ss) ---
u = 100, v = 200
*r = 200, *s = 100
rr points to 0x7ffd... (now holds original s's address)
ss points to 0x7ffd... (now holds original r's address)
r points to %p, s points to %p  (addresses swapped)
```

### 🧠 Why the Distinction Matters
| Aspect | `swap_int_contents(p, q)` | `swap_int_pointers(rr, ss)` |
|---|---|---|
| What changes? | The **integers** at the addresses `p` and `q` point to | The **pointer variables** `rr` and `ss` themselves |
| Dereference level | Dereference once (`*p`, `*q`) | Dereference zero times — just swap the addresses stored in `rr`/`ss` |
| Effect on original data | `x` and `y` swap values | `u` and `v` stay the same; `r` and `s` now point to each other's original targets |
| Common mistake | Forgetting to dereference → swaps pointer addresses instead of values | Accidentally dereferencing inside → ends up swapping both contents AND pointers (double-swap) |

### 💡 Takeaway
- Use **`swap_int_contents`** when you want to exchange the actual data behind two pointers.
- Use **`swap_int_pointers`** when you want to redirect two pointer variables to new targets without touching the data they point to.

Both rely on the same mechanic (temp variable + assignment), but the number of `*` operators completely changes *what* gets modified in memory.

Here's a memory-efficient Node.js function that reads a large file line-by-line using `readline` and `fs.createReadStream`, counts lines that fail `JSON.parse`, and never loads the whole file into memory:

```javascript
const fs = require('fs');
const readline = require('readline');

/**
 * Counts lines that fail JSON.parse in a large file,
 * reading one line at a time via streams.
 *
 * @param {string} filePath - Path to the file (JSONL or similar format)
 * @param {object} [options] - Optional config
 * @param {boolean} [options.skipEmptyLines=true] - Skip blank lines (they aren't JSON errors per se)
 * @returns {Promise<number>} Total count of JSON parse errors
 */
async function countJsonParseErrors(filePath, { skipEmptyLines = true } = {}) {
  return new Promise((resolve, reject) => {
    const rl = readline.createInterface({
      input: fs.createReadStream(filePath, { encoding: 'utf-8' }),
      crlfDelay: Infinity // treats \r\n, \n, and \r as line endings
    });

    let errorCount = 0;

    rl.on('line', (line) => {
      // Skip truly empty lines (optional)
      if (skipEmptyLines && line.trim() === '') return;

      // Optional: strip BOM (byte-order-mark) from the very first line
      const cleanedLine = line.startsWith('\uFEFF') ? line.slice(1) : line;

      try {
        JSON.parse(cleanedLine);
      } catch (err) {
        // Only SyntaxError means "not valid JSON"
        if (err instanceof SyntaxError) {
          errorCount++;
        }
      }
    });

    rl.on('close', () => resolve(errorCount));
    rl.on('error', reject);
  });
}

// ----- Example usage -----
(async () => {
  try {
    const path = 'large-file.jsonl'; // your big file
    const errors = await countJsonParseErrors(path);
    console.log(`JSON parse errors found: ${errors}`);
  } catch (err) {
    console.error('Failed to read file:', err.message);
  }
})();
```

### Why this works without loading memory:
- `fs.createReadStream` chunks the file and feeds it to `readline` incrementally.
- `readline` emits one `line` event at a time — only one line lives in memory at once.
- `JSON.parse` is called per line and immediately discarded.
- The only accumulated state is the `errorCount` number.
- `crlfDelay: Infinity` ensures cross-platform compatibility with `\n`, `\r`, and `\r\n`.
- Empty lines are optionally skipped (common in JSONL logs where blank lines exist between records).
- A BOM (byte-order-mark) at the start of the file is stripped to avoid false parse failures.

